 "content": "def transform(grid):
    """Infer a period and color sequence from nonzero diagonal stripes."""
    h, w = len(grid), len(grid[0])
    # For main-diagonal stripes, d = c-r. A clue stripe labels its residue.
    clues = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                d = c-r
                clues.setdefault(d, v)
    # Find the smallest period consistent with all observed stripe labels.
    offsets = list(clues)
    period = next((p for p in range(1, max(h,w)+1)
                   if all(not (a % p == b % p) or clues[a] == clues[b]
                          for i,a in enumerate(offsets) for b in offsets[i+1:])), max(h,w))
    # A period is often the inferred stripe-cycle length; fill the entire grid.
    residues = {}
    for d,v in clues.items():
        residues[d % period] = v
    if len(residues) < period:
        # extend between known diagonal colors in the cycle order by repetition
        known = sorted(residues)
        for x in range(period):
            if x not in residues:
                residues[x] = residues[min(known, key=lambda k: min((k-x)%period,(x-k)%period))]
    return [[residues[(c-r) % period] for c in range(w)] for r in range(h)]
