        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    groups.setdefault(keyfn(r, c), []).append(color)
        # Favor the diagonal orientation where clues form long, solid stripes.
        repeated = sum(len(v) for v in groups.values() if len(v) >= 2)
        consistent = sum(len(v) for v in groups.values() if len(set(v)) == 1)
        score = (repeated, consistent)
        clues = {k: v[0] for k, v in groups.items() if len(set(v)) == 1}
        return score, clues

    main_score, main_clues = inspect(lambda r, c: c-r)
    anti_score, anti_clues = inspect(lambda r, c: r+c)
    if anti_score > main_score:
        keyfn, clues = lambda r, c: r+c, anti_clues
    else:
